package com.shelf.launcher.ui

import com.shelf.launcher.R

/*
 * GENERATED by tools/media_templates/build.py + gen_kt.py from the template pack (C:\\Users\\User\\Downloads\\Templates):
 * the real empty cartridges / UMDs / cards (with and without each system's label frame), the disc overlays and
 * the 3D box glass overlays, with the label windows found from the pictures' alpha and the 3D boxes' front and
 * spine corners found from their outlines. Pictures: res/drawable-nodpi/tpl_*.webp. Don't edit by hand.
 *
 * Update 125 (by hand): the pack's spine strips (tpl_spine_*) are gone at your request; a 3D box's side shows the game's
 * real spine scan, else your own console spine (CustomSpines), else the side made from the box's front.
 */

/** A cartridge shell: its picture, the window mask, width / height, and the window's bounds (fractions l, t, r, b). */
internal class CartTpl(val res: Int, val mask: Int, val aspect: Float, val win: FloatArray)

/**
 * A 3D box: the glass overlay, width / height, the front face's corners (TL, TR, BR, BL as x, y fractions), the
 * spine's corners (TL, TR, BR, BL of the spine picture), whether the spine runs along the bottom (landscape boxes),
 * the system's spine strip, and the front frame (the system's printed border with a window for the art).
 */
internal class BoxTpl(
    val res: Int, val aspect: Float, val front: FloatArray, val spine: FloatArray, val hSpine: Boolean,
    val spineRes: Int?, val frameRes: Int?, val frameAspect: Float, val frameWin: FloatArray?
)

/** Everything the template pack has for one console. */
internal class MediaTpl(val cart: CartTpl?, val label: CartTpl?, val disc: Int?, val box: BoxTpl?)

